import{_ as e,o as l,c,O as d}from"./chunks/framework.b55d0e42.js";const u=JSON.parse('{"title":"基本操作","description":"","frontmatter":{},"headers":[],"relativePath":"TechToolkit/terminal/基本操作.md","filePath":"TechToolkit/terminal/基本操作.md","lastUpdated":1758873870000}'),a={name:"TechToolkit/terminal/基本操作.md"};function i(t,o,s,p,r,n){return l(),c("div",null,o[0]||(o[0]=[d('<h1 id="基本操作" tabindex="-1">基本操作 <a class="header-anchor" href="#基本操作" aria-label="Permalink to &quot;基本操作&quot;">​</a></h1><h2 id="常用快捷键" tabindex="-1">常用快捷键 <a class="header-anchor" href="#常用快捷键" aria-label="Permalink to &quot;常用快捷键&quot;">​</a></h2><ul><li><code>ctrl+c</code> 强制终止</li><li><code>ctrl+l</code> 清屏</li><li><code>ctrl+u</code> 删除或剪切之前命令</li><li><code>ctrl+y</code> 粘贴</li><li><code>ctrl+r</code> 搜索历史命令并执行</li><li><code>ctrl+d</code> 退出当前终端</li></ul><h2 id="ls-命令" tabindex="-1">ls 命令 <a class="header-anchor" href="#ls-命令" aria-label="Permalink to &quot;ls 命令&quot;">​</a></h2><ol><li><p>ls：显示目录文件（/bin/ls），选项[-ald] [文件或目录]</p><p>例：ls -a /home</p><p><code>-a</code> 显示所有文件，包括隐藏文件</p><p><code>-l</code> 详细信息显示</p><p><code>-d</code> 查看目录属性；</p></li><li><p>基本属性</p><p>文件类型：（<code>-</code> 文件 <code>d</code> 目录 <code>l</code> 软链接文件）</p><p><code>u</code> 所有者 <code>g</code>所属组 <code>o</code>其他人；</p><p><code>r</code> 读 <code>w</code> 写 <code>x</code>执行； x 执行：可以执行文件或进入目录等；</p></li></ol><h2 id="帮助命令" tabindex="-1">帮助命令 <a class="header-anchor" href="#帮助命令" aria-label="Permalink to &quot;帮助命令&quot;">​</a></h2><ol><li><code>which</code> 命令 搜索命令所在目录及别名信息；</li><li><code>whereis [命令名称]</code> 搜索命令所在目录及帮助文档路径；</li><li><code>man [命令或配置文件]</code> 获得帮助信息；</li><li><code>help</code> 命令 获得内置 shell 命令的帮助信息；</li><li><code>whatis</code> 查看命令的简短信息</li><li><code>apropos</code> 查看配置文件的简短信息</li><li><code>info</code> 等同于 man 命令</li></ol><h2 id="用户管理命令" tabindex="-1">用户管理命令 <a class="header-anchor" href="#用户管理命令" aria-label="Permalink to &quot;用户管理命令&quot;">​</a></h2><ol><li><code>useradd 用户名</code> 添加新用户，root 用户执行；</li><li><code>passwd 用户名</code> 设置用户密码；</li><li><code>who</code> 查看登录用户信息；</li><li><code>w</code> 查看登录用户详细信息；</li></ol><h2 id="网络命令" tabindex="-1">网络命令 <a class="header-anchor" href="#网络命令" aria-label="Permalink to &quot;网络命令&quot;">​</a></h2><ol><li><p><code>write 用户名</code> 给用户发信息，以 ctrl+d 保存结束；</p></li><li><p><code>wall [message]</code> 发广播信息，给广播发信息；</p></li><li><p><code>ping [-c] ip地址</code> 测试网络连通性，-c 指定发送次数；</p></li><li><p><code>mail [用户名]</code> 查看发送电子邮件</p><p><code>mail</code> 回车 读取信息（<code>h</code> 查看列表， <code>d[序列号]</code>删除邮件）</p></li><li><p><code>ifconfig</code> 查看设置网卡信息</p></li><li><p><code>last</code> 查看目前与过去登入系统的用户信息；</p></li><li><p><code>lastlog</code> 检查某特定用户上次登录的时间</p><p><code>lastlog -u 500</code>； 通过 uid 查看指定用户的登录信息；</p></li><li><p><code>traceroute 地址</code> 显示数据包到主机间的路径；</p></li><li><p><code>netstat [选项]</code> 显示网络相关信息；</p><p><code>-t</code> TCP 协议；<code>-u</code> UDP 协议；<code>-l</code> 监听；<code>-r</code> 路由 <code>-n</code> 显示 ip 地址和端口号</p><p>示例：</p><ul><li><code>netstat -tlun</code> 查看本地监听的端口</li><li><code>netstat -an</code> 查看本机所有的网络连接；</li><li><code>netstat -rn</code> 查看本机路由表；</li></ul></li><li><p><code>setup</code> 配置网络；<code>service network restart</code>重启网络配置才会生效</p></li><li><p><code>mount [-t文件系统] 设备文件名</code> 挂载点</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#B392F0;">mount</span><span style="color:#E1E4E8;"> </span><span style="color:#79B8FF;">-t</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">iso9660</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">/dev/sr0</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">/mnt/cdrom</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#6F42C1;">mount</span><span style="color:#24292E;"> </span><span style="color:#005CC5;">-t</span><span style="color:#24292E;"> </span><span style="color:#032F62;">iso9660</span><span style="color:#24292E;"> </span><span style="color:#032F62;">/dev/sr0</span><span style="color:#24292E;"> </span><span style="color:#032F62;">/mnt/cdrom</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><p><code>unmount</code> 卸载 <code>umount /mnt/cdrom</code> 卸载光盘</p></li><li><p><code>curl [options] [url]</code></p><p>常用 options：</p><ul><li><code>-o</code> 把输出写到该文件中</li><li><code>-I</code> 仅仅返回 header</li></ul><p>常用的场景：</p><ul><li><code>curl localhost:2222/getlist</code>：调试请求</li><li><code>curl -I www.taobao.com</code>：查看头部信息</li><li><code>curl -o index.html www.baidu.com</code>：抓取网页，会将 index.html 下载下来</li></ul></li></ol><h2 id="系统管理" tabindex="-1">系统管理 <a class="header-anchor" href="#系统管理" aria-label="Permalink to &quot;系统管理&quot;">​</a></h2><h4 id="kill-杀死进程" tabindex="-1">kill 杀死进程 <a class="header-anchor" href="#kill-杀死进程" aria-label="Permalink to &quot;kill 杀死进程&quot;">​</a></h4><p>通过 ps 指令或 jobs 指令查看 pid，获取 pid 之后杀死进程</p><ul><li><code>-15</code>：终止程序</li><li><code>-9</code>：尝试强制删除程序</li></ul><p>也可以直接使用<code>kill pid码</code></p><h4 id="top-实时显示进程动态" tabindex="-1">top 实时显示进程动态 <a class="header-anchor" href="#top-实时显示进程动态" aria-label="Permalink to &quot;top 实时显示进程动态&quot;">​</a></h4><p><code>top [-pid] id</code> 指定进入 id</p><h4 id="alias-别名配置" tabindex="-1">alias 别名配置 <a class="header-anchor" href="#alias-别名配置" aria-label="Permalink to &quot;alias 别名配置&quot;">​</a></h4><p><code>alias[别名]=[指令名称]</code> 修改别名</p><p><code>vi /root/.bashrc</code> 定义别名永久生效</p><p><code>unalias 别名</code> 删除别名</p><h4 id="history-历史命令" tabindex="-1">history 历史命令 <a class="header-anchor" href="#history-历史命令" aria-label="Permalink to &quot;history 历史命令&quot;">​</a></h4><p><code>history</code> 显示历史命令</p><p><code>-c</code>清楚 <code>-w</code>把缓存命令写进<code>.bash_history</code><code>/etc/profile</code> 修改历史命令条数 <code>/root/.bash_history</code> 保存在家目录下 调用历史命令</p><ul><li><code>!n</code> 重复第几条命令</li><li><code>!!</code> 重复执行上一条</li><li><code>!字串</code> 重复执行含有该字串的命令</li></ul><h2 id="关机开机" tabindex="-1">关机开机 <a class="header-anchor" href="#关机开机" aria-label="Permalink to &quot;关机开机&quot;">​</a></h2><ul><li><p>服务器连续运行时间： <code>uptime</code></p></li><li><p>重启：<code>rebort</code></p></li><li><p>关机：<code>shutdown</code></p><ul><li><code>now</code> 现在关机 <code>shutdown -h now</code> 现在关机</li><li><code>-h</code> 指定时间关机 <code>shutdown -h 20:30</code> 八点半关机</li><li><code>-r</code> 重启</li><li><code>-c</code> 取消前一个关机</li></ul></li><li><p>系统运行级别</p><p><code>0</code>关机 <code>1</code>单用户 <code>2</code>不完全多用户 <code>3</code>字符界面 <code>4</code>未分配 <code>5</code>图形界面 <code>6</code>重启 <code>id:3:initdefault:</code> 修改系统默认运行级别 <code>runlevel</code> 查询当前运行级别 <code>logout</code> 退出登录</p></li></ul>',28)]))}const m=e(a,[["render",i]]);export{u as __pageData,m as default};
